#include "keyed-column-transposition.h"

std::optional<std::string> charm::v1n7::crypto_square::keyed_column_encode(std::string_view text,std::string_view key,char pad){if(key.empty()||std::isalnum(static_cast<unsigned char>(pad)))return std::nullopt;for(char c:key)if(!std::isalnum(static_cast<unsigned char>(c)))return std::nullopt;std::string clean;for(char c:text)if(std::isalnum(static_cast<unsigned char>(c)))clean.push_back(static_cast<char>(std::tolower(static_cast<unsigned char>(c))));std::size_t rows=(clean.size()+key.size()-1)/key.size();clean.resize(rows*key.size(),pad);std::vector<std::size_t> order(key.size());std::iota(order.begin(),order.end(),0);std::stable_sort(order.begin(),order.end(),[&](auto a,auto b){char x=static_cast<char>(std::tolower(static_cast<unsigned char>(key[a]))),y=static_cast<char>(std::tolower(static_cast<unsigned char>(key[b])));return x<y;});std::string out;for(std::size_t col:order)for(std::size_t row=0;row<rows;++row)out.push_back(clean[row*key.size()+col]);return out;}
